head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[column > P > editDisplayChar]<br/>inputType='text' 인 Column 에서 마스킹 처리된 범위에 Cell 값 대신 표시될 문자를 설정합니다.",
    "validation" : [
        "Column 의 editFormat 속성에 '{,}'(중괄호) 기호로 설정된 마스크 문자가 있고, 해당 범위에 Cell 값이 있을때 동작합니다.",
        "문자열 설정 시, 마스킹 처리된 범위에 Cell 값 대신 표시될 문자를 설정합니다.",
        "속성값을 설정하지 않으면 마스킹 범위여도 Cell 값이 그대로 표시됩니다.",
        "editDisplayChar 속성은 Column 의 편집 상태 여부와 관계없이 모두 적용됩니다.",
        "Column 의 editPlaceholderChar 가 설정된 경우 마스킹 범위에 Cell 값이 없으면 editPlaceholderChar 속성에 설정된 문자가 표시되고, Cell 값이 있으면 editDisplayChar 속성에 설정된 문자가 표시됩니다.",
        "중괄호 '{ }' 로 감싼 구간의 자리에 editDisplayChar 속성의 문자가 표시됩니다.",
        "중괄호로 감싸지 않은 '*' 마스크 문자도 '*' 대신 editDisplayChar 속성의 문자가 표시됩니다.",
        "중괄호 구간 안이라도 '!' 마스크 문자로 이스케이프한 자리는 고정 문자로 취급되어 editDisplayChar 속성의 문자가 적용되지 않습니다.",
        "Column 의 customFormatter 속성을 설정하면 editDisplayChar 속성이 적용된 표시 텍스트가 사용자 함수의 두번째 파라미터로 전달되고, 사용자 함수의 반환값이 Cell 에 표시됩니다.",
    ]
}



scwin.gVar = {
    // Row 별 바인딩 값 (Row 0 : 마스킹 범위까지 모두 입력 / Row 1 : 마스킹 범위 앞까지만 입력 / Row 2 : 마스킹 범위 일부 입력)
    "rowValues" : ["9001011234567", "9001011", "9001011234"],
    // customFormatter 사용자 함수의 Row 인덱스별 두 번째 파라미터 (Target 생성 시 초기화)
    "customParams" : {},
    // 편집 중 입력창 값 기록 (셀 더블클릭 시 초기화)
    "editRow" : -1,
    "editValue" : []
}



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정
    con_editFormat.setValue("######-#{######}");
    con_editDisplayChar.setValue("*");
    con_editPlaceholderChar.setValue("");
    con_customFormatter.setValue("");

    // comp 초기 생성
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// customFormatter 로 지정하는 사용자 함수 (두 번째 파라미터를 기록하고 대괄호로 감싸 반환)
scwin.custom_bracket = function (data, formattedData, rowIndex, columnIndex) {
    scwin.gVar.customParams[rowIndex] = formattedData;
    return "[" + formattedData + "]";
}



// comp 생성
//  - raw : 원본값 Column (readOnly)
//  - val : 검증 대상 Column (inputType=text, editFormat / editDisplayChar / editPlaceholderChar / customFormatter 를 옵션값으로 설정)
scwin.comp_init = async function () {
    // 기존 target / dataList / label 삭제
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove("dlt_bind");
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }
    scwin.gVar.customParams = {};
    scwin.gVar.editRow = -1;
    scwin.gVar.editValue = [];

    // 테스트 정보 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] Row 0 은 마스킹 범위까지 모두 입력된 값, Row 1 은 마스킹 범위 앞까지만 입력된 값, Row 2 는 마스킹 범위 일부만 입력된 값\n[절차] 조건 선택 -> Target 재생성 -> 셀 표시값 확인\n[절차] 결과창 clear -> val 셀 더블클릭 -> 숫자 13자리 (예: 8505052345678) 를 한 자씩 입력 (기존 값은 대체됨) -> 셀 밖 클릭으로 포커스 해제 -> 셀 표시값 확인\n[확인] 편집 중 입력창 값과 편집 상태가 아닐때의 셀 표시값, DataList 값 비교"', '', 'label1');

    let cEditFormat = con_editFormat.getValue();
    let cEditDisplayChar = con_editDisplayChar.getValue();
    let cEditPlaceholderChar = con_editPlaceholderChar.getValue();
    let cCustomFormatter = con_customFormatter.getValue();

    // dataList 생성 (body column id 와 동일한 컬럼 id 사용)
    let strNameSpace = $c.gcm.getNameSpace();
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="raw" name="raw" dataType="text"></w2:column>';
    strDlt += '<w2:column id="val" name="val" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    let arrData = [];
    for (let i = 0; i < scwin.gVar.rowValues.length; i++) {
        arrData.push({ "raw" : scwin.gVar.rowValues[i], "val" : scwin.gVar.rowValues[i] });
    }
    dlt_bind.setJSON(arrData, false);

    // val Column 속성 (미설정 옵션은 속성 자체를 넣지 않는다)
    let attrVal = ' inputType="text" dataType="text" editFormat="' + cEditFormat + '"';
    if (cEditDisplayChar !== '') {
        attrVal += ' editDisplayChar="' + cEditDisplayChar + '"';
    }
    if (cEditPlaceholderChar !== '') {
        attrVal += ' editPlaceholderChar="' + cEditPlaceholderChar + '"';
    }
    if (cCustomFormatter !== '') {
        attrVal += ' customFormatter="' + cCustomFormatter + '"';
    }

    // target 생성
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" checkAllType="false" id="" style="width:560px;height:120px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="200" style="" inputType="text" id="column1" value="원본값"></w2:column>';
    strTarget += '<w2:column width="340" style="" inputType="text" id="column2" value="val (' + cEditFormat + ')"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="200" style="" inputType="text" id="raw" value="" readOnly="true"></w2:column>';
    strTarget += '<w2:column width="340" style="" id="val" value=""' + attrVal + '></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    // 편집 입력창 값 기록
    //  - 셀 더블클릭(편집 진입) 시 기록을 초기화하고 편집 진입 직후 입력창 값을 첫 값으로 기록
    //  - 키를 뗄 때마다 입력창 값 기록
    target1.render.addEventListener("dblclick", function () {
        scwin.gVar.editValue = [];
        setTimeout(function () {
            scwin.gVar.editRow = target1.getFocusedRowIndex();
            let elem = document.activeElement;
            if (elem && elem.tagName === "INPUT" && target1.render.contains(elem)) {
                scwin.gVar.editValue.push(elem.value);
            }
        }, 0);
    }, true);
    target1.render.addEventListener("keyup", scwin.recordEditValue, true);
}



// 편집 중 키를 뗄 때마다 입력창 값을 기록 (입력창의 포맷 처리가 끝난 뒤의 값을 읽는다)
scwin.recordEditValue = function (e) {
    let elem = e.target;
    if (!elem || elem.tagName !== "INPUT") {
        return;
    }
    setTimeout(function () {
        let arr = scwin.gVar.editValue;
        if (arr.length === 0 || arr[arr.length - 1] !== elem.value) {
            arr.push(elem.value);
        }
    }, 0);
}



// val 셀의 화면 표시값
scwin.getCellText = function (rowIndex) {
    let td = document.querySelector("td[id*='" + target1.id + "_cell_" + rowIndex + "_1']");
    return td ? td.textContent : "";
}



// 설정 조건, Row 별 DataList 값 -> (customFormatter 두 번째 인자) -> 셀 표시값, 편집 중 입력창 값 출력
//  - validation 1 : editFormat 중괄호 유무 / Row 1 (마스킹 범위에 값 없음) 셀 표시값
//  - validation 2, 3 : editDisplayChar 설정 / 미설정 시 셀 표시값
//  - validation 4 : 편집 중 입력창 값과 편집 상태가 아닐때의 셀 표시값
//  - validation 5 : editPlaceholderChar 설정 시 Row 1, 2 셀 표시값
//  - validation 6, 7, 8 : editFormat (중괄호 / 중괄호 밖 * / 중괄호 안 ! 이스케이프) 별 셀 표시값
//  - validation 9 : customFormatter 두 번째 파라미터와 셀 표시값
scwin.btn_checkCell_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    let cEditDisplayChar = con_editDisplayChar.getValue();
    let cEditPlaceholderChar = con_editPlaceholderChar.getValue();
    let cCustomFormatter = con_customFormatter.getValue();

    let arrCond = ["editFormat : " + con_editFormat.getValue(), "editDisplayChar : " + (cEditDisplayChar === '' ? "(미설정)" : cEditDisplayChar)];
    if (cEditPlaceholderChar !== '') {
        arrCond.push("editPlaceholderChar : " + cEditPlaceholderChar);
    }
    if (cCustomFormatter !== '') {
        arrCond.push("customFormatter : " + cCustomFormatter);
    }
    bottom.setReturnValue(arrCond.join(" / "));

    for (let i = 0; i < scwin.gVar.rowValues.length; i++) {
        let arrText = ["Row " + i + " DataList 값 : " + dlt_bind.getCellData(i, "val")];
        if (cCustomFormatter !== '') {
            let param = scwin.gVar.customParams[i];
            arrText.push("customFormatter 두 번째 인자 : " + (typeof param === "undefined" ? "호출 안 됨" : param));
        }
        arrText.push("셀 표시값 : " + scwin.getCellText(i));
        bottom.setReturnValue(arrText.join(" -> "));
    }

    // 편집하지 않았으면 편집 줄은 출력하지 않는다
    if (scwin.gVar.editRow < 0 || scwin.gVar.editValue.length === 0) {
        return;
    }
    bottom.setReturnValue("Row " + scwin.gVar.editRow + " 편집 중 입력창 값 : " + scwin.gVar.editValue.join(" > "));
}
